// src/pages/AudienceGate.jsx
import React, { useRef, useState } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { setAudience } from '../utils/audience';
import axios from 'axios';

export default function AudienceGate() {
  const nav = useNavigate();
  const loc = useLocation();
  const rootRef = useRef(null);
  const [animating, setAnimating] = useState(false);

  const goHome = () => {
    const to =
      (loc.state && loc.state.from)
        ? loc.state.from.pathname + (loc.state.from.search || '')
        : '/';
    nav(to, { replace: true });
  };

  const choose = (value) => {
    if (animating) return;
    setAnimating(true);
    setAudience(value);
    axios.defaults.headers.common['X-Audience'] = value;

    // disparamos animación CSS (logo -> posición del hero de la home)
    const root = rootRef.current;
    if (root) {
      root.classList.add('ag-to-hero');
      // cuando termina la animación CSS, navegamos
      const onEnd = () => {
        root.removeEventListener('transitionend', onEnd);
        goHome();
      };
      root.addEventListener('transitionend', onEnd);
      // Fallback por si algún navegador no dispara transitionend
      setTimeout(goHome, 500);
    } else {
      goHome();
    }
  };

  return (
    <div ref={rootRef} className="ag-root">
      <img src="/logo.png" alt="Conecta Pinamar" className="ag-logo" />
      <div className="ag-split">
        <button className="ag-side left" onClick={() => choose('RESIDENT')}>
          <span className="ag-label">SOY RESIDENTE</span>
        </button>
        <button className="ag-side right" onClick={() => choose('TOURIST')}>
          <span className="ag-label">SOY TURISTA</span>
        </button>
      </div>
    </div>
  );
}
